import { db } from '@/libs/db';
export async function obtenerTiposDeDocumento() {
    try {
        const [rows] = await db.query('SELECT TIPO, ESTADO FROM TIPO_DOCUMENTO');
        return rows as { id: string; est: boolean }[];
    } catch (error) {
        console.error('Error al obtener tipos de documento:', error);
        throw new Error('No se pudo cargar la lista de tipos de documento');
    }
}
